pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address attacker, uint256 amount) public {
        vm.assume(attacker != address(0));
        vm.assume(attacker != address(c));
        vm.assume(attacker != c.Owner());
        vm.assume(amount > 0);

        vm.deal(address(c), amount);
        vm.prank(attacker);
        try c.withdraw() {
            // If withdraw succeeds for the attacker, the balance should still be the original amount
            // because only the owner should be able to withdraw.
            // In the buggy version, the attacker can withdraw, so the balance will decrease.
            assertEq(address(c).balance, amount);
        } catch {
            // If it reverts, the balance should remain unchanged.
            assertEq(address(c).balance, amount);
        }
    }
}

