pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, uint256 initialBalance, uint256 extra) public {
        vm.assume(owner != address(0));
        vm.assume(owner != address(c));
        vm.assume(initialBalance <= type(uint256).max / 2);
        vm.assume(extra <= type(uint256).max / 2);
        vm.deal(address(c), initialBalance);
        vm.prank(owner);
        // Set Owner by sending funds; this will make msg.sender the Owner
        // payable(address(c)).transfer(0) sets Owner = tx.origin for the first interaction
        // Use Command with empty calldata to set Owner without breaking balance invariant check
        // Actually, Constructor sets Owner = msg.sender (the test contract). We need a fuzzed owner.
        // We redeploy C with the fuzzed owner using a helper: we can vm.prank(owner) new C() but setUp() is fixed.
        // Instead, we transfer ownership: we can use the fact that Owner is public and has no setter.
        // We can't change owner; we must test with the owner set during setUp() = address(this).
        // So the fuzzed owner param is unused but required; we test with the actual owner.
        // We'll use the fuzzed owner only to pre-fund if needed, but the invariant still holds for any initial balance.
        // Actually, we can still fuzz initialBalance and extra, and check balance after withdraw.
        // The owner is address(this) from setUp(). That's fine; fuzz the balance values.
        // We also need to ensure we don't revert on multiplicate if called, but we only call withdraw.
        uint256 preOwnerBal = address(c).balance;
        // The owner is this test contract (from setUp). Ensure we have enough balance to cover gas, not needed for transfer check.
        vm.prank(address(this));
        c.withdraw();
        uint256 postOwnerBal = address(c).balance;
        // After withdraw, contract balance must be 0 and owner received preOwnerBal
        assertTrue(postOwnerBal == 0);
    }
}

