pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, uint256 seedBalance, uint256 dust) public {
        // restrict to admissible range: seedBalance fit in uint256 and avoid overflow
        vm.assume(seedBalance <= type(uint256).max / 2);
        vm.assume(dust <= seedBalance);
        // avoid zero-address
        vm.assume(owner != address(0));

        // fund contract
        vm.deal(address(c), seedBalance);
        // set owner to a fuzzed address (works because C sets Owner=msg.sender during construction)
        // we need to change the owner; deploy a new C with a pranked sender
        // but setUp already deployed with msg.sender. To let fuzzer pick owner, we need to
        // construct a fresh C with fuzzed owner. Use vm.prank for constructor:
        vm.prank(owner);
        c = new C();
        // fund it again after deployment
        vm.deal(address(c), seedBalance);

        uint256 balanceBefore = address(c).balance;
        // call withdraw as owner
        vm.prank(owner);
        c.withdraw();
        uint256 balanceAfter = address(c).balance;

        // The reference transfers full balance to owner (balance becomes 0);
        // the mutant transfers 0 (balance unchanged).
        // The invariant we check: either balance changed to 0, or it stayed the same.
        // The reference always makes it 0, the mutant always leaves it unchanged.
        // We assert a weak property true for reference: balanceAfter == 0 || balanceAfter == balanceBefore.
        // Reference: balanceAfter == 0 (true for the OR). Mutant: balanceAfter == balanceBefore (true for the OR).
        // But we need reference to hold for ALL inputs and mutant to FAIL for SOME input.
        // The mutant always makes balanceAfter == balanceBefore (true), so it would pass this assertion.
        // Instead, we must assert something the mutant violates. Since the mutant always pays 0,
        // the contract balance never decreases. The reference always pays full balance, so balance decreases.
        // A property: if balanceBefore > 0, then balanceAfter < balanceBefore (reference true).
        // The mutant violates this when seedBalance > 0.
        if (balanceBefore > 0) {
            assertTrue(balanceAfter < balanceBefore);
        } else {
            // when balanceBefore == 0, both transfer 0, balance stays 0; we assert nothing or a trivial true.
            assertTrue(true);
        }
    }
}

