pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 extraDeposit) public {
        // Restrict to a reasonable domain that keeps the invariant testable.
        // We need at least one wei deposited so the Owner has something to gain.
        vm.assume(depositAmount > 0 && depositAmount <= type(uint128).max);
        vm.assume(extraDeposit <= type(uint128).max);

        // Make the Owner a distinct, funded address so we can measure their balance change.
        address owner = makeAddr("owner");
        vm.deal(owner, 100 ether);

        // Deploy C as the fuzzed owner by pranking the constructor.
        vm.startPrank(owner);
        c = new C();
        vm.stopPrank();

        // Deposit ether into C from an arbitrary sender to create a non-zero balance.
        vm.deal(address(this), depositAmount + extraDeposit);
        vm.prank(address(this));
        (bool sent,) = address(c).call{value: depositAmount}("");
        require(sent, "initial deposit failed");

        // Add another deposit that does not affect the invariant but mixes the state.
        if (extraDeposit > 0) {
            vm.prank(address(this));
            (bool extraSent,) = address(c).call{value: extraDeposit}("");
            require(extraSent, "extra deposit failed");
        }

        uint256 preOwnerBalance = owner.balance;

        // Owner calls withdraw.
        vm.prank(owner);
        try c.withdraw() returns (bytes memory) {
            // withdraw succeeded
        } catch {
            // If withdraw reverts the invariant is vacuously true for that run;
            // we only care about successful withdrawals.
            return;
        }

        uint256 postOwnerBalance = owner.balance;
        // General rule: after a successful withdraw, the Owner's balance MUST increase.
        // The buggy version transfers 0, so the Owner's balance stays the same -> assertion fails.
        assertTrue(postOwnerBalance > preOwnerBalance);
    }
}

