import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint8 seed) public {
        // 1. restrict to a wide admissible domain: contract must be fundable and owner must be able to withdraw
        address owner = c.Owner();
        // keep amount positive but not astronomically large; bound to a wide range that avoids overflow in vm.deal
        amount = bound(amount, 1, type(uint128).max);
        // 2. fund the contract by sending from an arbitrary address (not the owner, to simulate a real scenario)
        address funder = address(uint160(uint256(keccak256(abi.encodePacked(seed, uint8(1))))));
        vm.deal(funder, amount);
