        // owner withdraws
        vm.prank(owner);
        try c.withdraw() {
            uint256 balAfter = address(c).balance;
            // 3. property: after a successful withdraw by the owner, the contract balance MUST decrease
            assertTrue(balAfter < balBefore);
        } catch {
            // if withdraw reverts, the property is vacuously true; nothing to assert
        }
    }
}

